package org.sleepwell.app;

import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.Semaphore;
import java.util.function.BooleanSupplier;
import java.util.zip.*;

/** Read-only effective-interval export. Each gap is a file boundary, never silence invented in PCM. */
final class AacArchive {
    static final int MAX_PARTS=60,MAX_ROWS=3600;static final long MAX_BYTES=64L*1024*1024;
    static final class Source {final JSONObject clip;final long bytes;final String hash;final AacPcmEncoder.Pcm pcm;final List<JSONObject> events;Source(JSONObject clip,long bytes,String hash,AacPcmEncoder.Pcm pcm,List<JSONObject> events){this.clip=clip;this.bytes=bytes;this.hash=hash;this.pcm=pcm;this.events=List.copyOf(events);}}
    static final class Part {final Source source;final RecordEntry night;final JSONObject event;final long first,end,startWall,endWall;final String title;Part(Source source,RecordEntry night,JSONObject event,long first,long end,long startWall,long endWall){this.source=source;this.night=night;this.event=event;this.first=first;this.end=end;this.startWall=startWall;this.endWall=endWall;title=event==null?"Recording":SoundLabels.title(event);}long duration(){return (end-first)*1000/source.pcm.rate;}}
    static final class Plan {final List<Part> parts;final String fingerprint;final long bytes;final int withoutAudio,outside;Plan(List<Part> parts,String fingerprint,long bytes,int withoutAudio,int outside){this.parts=List.copyOf(parts);this.fingerprint=fingerprint;this.bytes=bytes;this.withoutAudio=withoutAudio;this.outside=outside;}}
    private static final class Raw {final List<JSONObject> clips,events;final Map<Long,RecordEntry> nights;final String fingerprint;Raw(List<JSONObject> clips,List<JSONObject> events,Map<Long,RecordEntry> nights,String fingerprint){this.clips=clips;this.events=events;this.nights=nights;this.fingerprint=fingerprint;}}
    private static IOException limit(){return new IOException("This export supports at most 60 audio parts and 64 MB of original recordings. Export a smaller night or selection; nothing was truncated.");}
    private static Raw metadata(Store store,long record,boolean favorites)throws Exception {
        SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{
            String scope=favorites?" AND (c.favorite=1 OR EXISTS(SELECT 1 FROM sound_events e WHERE e.clip=c.id AND e.session=c.session AND e.favorite=1))":" AND c.session=CAST(? AS INTEGER)";
            List<JSONObject> clips=favorites?store.rows("SELECT c.* FROM clips c JOIN sessions s ON s.id=c.session WHERE s.end IS NOT NULL"+scope+" ORDER BY c.session,c.time,c.id LIMIT 61"):store.rows("SELECT c.* FROM clips c JOIN sessions s ON s.id=c.session WHERE s.end IS NOT NULL"+scope+" ORDER BY c.time,c.id LIMIT 61",""+record);
            List<JSONObject> events=favorites?store.rows("SELECT e.* FROM sound_events e JOIN sessions s ON s.id=e.session WHERE s.end IS NOT NULL AND e.favorite=1 ORDER BY e.session,e.time,e.id LIMIT 3601"):store.rows("SELECT * FROM sound_events WHERE session=CAST(? AS INTEGER) ORDER BY time,id LIMIT 3601",""+record);
            if(clips.size()>MAX_PARTS||events.size()>MAX_ROWS)throw limit();Map<Long,RecordEntry> nights=new LinkedHashMap<>();JSONArray snapshot=new JSONArray();for(JSONObject clip:clips){long id=clip.getLong("session");if(!nights.containsKey(id))nights.put(id,Records.get(store,id));if(SoundClips.pending(store,clip.getLong("id")))throw new IOException("Finish pending recording deletions before exporting.");}
            if(!favorites&&record>0&&!nights.containsKey(record))nights.put(record,Records.get(store,record));
            for(RecordEntry night:nights.values()){JSONArray coverage=new JSONArray();for(RecordIntervals.Span span:night.coverage())coverage.put(new JSONArray().put(span.start).put(span.end));snapshot.put(new JSONObject().put("id",night.id).put("start",night.rawStart).put("end",night.rawEnd).put("updated",night.updated).put("source",night.source).put("origin",night.origin).put("sensor",night.sensor).put("zone",night.zone).put("coverage",coverage));}
            String fingerprint=hash(new JSONObject().put("clips",new JSONArray(clips)).put("events",new JSONArray(events)).put("nights",snapshot).toString().getBytes(StandardCharsets.UTF_8));db.setTransactionSuccessful();return new Raw(clips,events,nights,fingerprint);
        }finally{db.endTransaction();}
    }
    static Plan prepare(Context app,Store store,long record,boolean favorites,BooleanSupplier active)throws Exception {
        if(!favorites&&record<=0)throw new IOException("Choose a recorded night first.");synchronized(SoundClips.LOCK){Raw raw=metadata(store,record,favorites);Map<Long,Source> sources=new LinkedHashMap<>();long bytes=0;
            for(JSONObject clip:raw.clips){NightAudioArchive.active(active);try(RandomAccessFile in=new RandomAccessFile(FileSafety.clip(app,clip.getString("path")),"r")){long size=in.length();bytes=Math.addExact(bytes,size);if(bytes>MAX_BYTES)throw limit();AacPcmEncoder.Pcm pcm=AacPcmEncoder.inspect(in);List<JSONObject> linked=new ArrayList<>();for(JSONObject event:raw.events)if(!event.isNull("clip")&&event.optLong("clip")==clip.getLong("id")){if(event.optLong("session")!=clip.getLong("session"))throw new IOException("A sound event has an invalid recording link.");linked.add(event);}sources.put(clip.getLong("id"),new Source(clip,size,copy(in,null,size,active),pcm,linked));}}
            List<Part> parts=new ArrayList<>();Set<String> unique=new HashSet<>();int missing=0,outside=0;
            if(favorites){for(JSONObject event:raw.events){Source source=sources.get(event.optLong("clip"));if(source==null){missing++;continue;}if(!add(parts,unique,source,raw.nights.get(source.clip.getLong("session")),event,event.getLong("time"),Math.addExact(event.getLong("time"),event.getLong("duration_ms"))))outside++;}
                for(Source source:sources.values())if(source.clip.optInt("favorite")==1&&!add(parts,unique,source,raw.nights.get(source.clip.getLong("session")),null,Long.MIN_VALUE,Long.MAX_VALUE))outside++;
            }else for(Source source:sources.values())if(!add(parts,unique,source,raw.nights.get(record),null,Long.MIN_VALUE,Long.MAX_VALUE))outside++;
            if(!metadata(store,record,favorites).fingerprint.equals(raw.fingerprint))throw new IOException("The recordings changed. Refresh the export review.");return new Plan(parts,raw.fingerprint,bytes,missing,outside);
        }
    }
    private static boolean add(List<Part> parts,Set<String> unique,Source source,RecordEntry night,JSONObject event,long eventStart,long eventEnd)throws Exception {
        long clipEnd=source.clip.getLong("time"),clipStart=Math.subtractExact(clipEnd,source.pcm.duration()),start=Math.max(clipStart,eventStart),end=Math.min(clipEnd,eventEnd);boolean included=false;
        for(RecordIntervals.Span span:RecordIntervals.intersect(night.coverage(),start,end)){long first=((span.start-clipStart)*source.pcm.rate+999)/1000,last=Math.min(source.pcm.frames,(span.end-clipStart)*source.pcm.rate/1000);if(last<=first)continue;String key=source.clip.getLong("id")+":"+first+":"+last;if(unique.add(key)){if(parts.size()>=MAX_PARTS)throw limit();parts.add(new Part(source,night,event,first,last,span.start,span.end));}included=true;}return included;
    }
    static String hash(byte[] bytes)throws Exception{return NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(bytes));}
    private static String copy(RandomAccessFile in,OutputStream out,long expected,BooleanSupplier active)throws Exception {in.seek(0);MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] data=new byte[65536];long total=0;for(int n;(n=in.read(data))!=-1;){NightAudioArchive.active(active);total+=n;if(total>expected)throw new IOException("A recording changed.");digest.update(data,0,n);if(out!=null)out.write(data,0,n);}if(total!=expected||in.length()!=expected)throw new IOException("A recording changed.");return NightAudioArchive.hash(digest.digest());}
    static final class Snapshot implements AutoCloseable {
        final Workspace workspace;final List<Part> parts;final List<File> encoded=new ArrayList<>();byte[] manifest;
        Snapshot(Workspace workspace,List<Part> parts){this.workspace=workspace;this.parts=parts;}
        void encode(BooleanSupplier active,java.util.function.IntConsumer progress)throws Exception {final long deadline=android.os.SystemClock.elapsedRealtime()+300000;BooleanSupplier encoding=()->active.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<=deadline;JSONArray entries=new JSONArray();long size=0;for(int i=0;i<parts.size();i++){NightAudioArchive.active(active);Part part=parts.get(i);File output=workspace.file(i,"m4a");AacPcmEncoder.encode(workspace.source(part.source),output,part.first,part.end,encoding);encoded.add(output);size+=output.length();if(size>MAX_BYTES)throw limit();String digest;try(RandomAccessFile in=new RandomAccessFile(output,"r")){digest=copy(in,null,in.length(),active);}JSONObject item=new JSONObject().put("file",String.format(Locale.ROOT,"recordings/%03d.m4a",i+1)).put("bytes",output.length()).put("sha256",digest).put("source_wav_sha256",part.source.hash).put("source_clip_id",part.source.clip.getLong("id")).put("source_session_id",part.night.id).put("source_provenance",part.night.provenance()).put("source_sensor",part.night.sensor).put("source_zone",part.night.zone).put("requested_start",part.startWall).put("requested_end",part.endWall).put("pcm_first_frame",part.first).put("pcm_end_frame",part.end).put("pcm_rate",part.source.pcm.rate).put("pcm_channels",part.source.pcm.channels).put("pcm_duration_ms",part.duration()).put("favorite",part.source.clip.optInt("favorite")==1||part.event!=null&&part.event.optInt("favorite")==1);
                JSONArray estimates=new JSONArray();for(JSONObject event:part.event==null?part.source.events:List.of(part.event)){long start=event.getLong("time"),end=Math.addExact(start,event.getLong("duration_ms"));if(start>=part.endWall||end<=part.startWall)continue;JSONObject estimate=new JSONObject();for(String key:List.of("id","time","duration_ms","category","score","model","favorite","user_category","label_revision"))estimate.put(key,event.has(key)?event.get(key):JSONObject.NULL);estimate.put("effective_category",SoundLabels.category(event)).put("label_source",SoundLabels.manual(event)?"user":"model");estimates.put(estimate);}item.put("sound_events",estimates);entries.put(item);progress.accept(i+1);}
            manifest=new JSONObject().put("format","sleepwell-aac-export").put("version",1).put("codec","AAC-LC").put("container","MPEG-4 audio").put("scope","selected_effective_recorded_intervals").put("note","Each file is one real PCM interval. Pauses, missing capture and reviewed awake exclusions are not joined or filled. AAC is lossy and may add codec padding at file boundaries. Estimates are not validated sleeper identities or medical findings. Originals remain unchanged. This export is not a SleepWell restore archive.").put("recordings",entries).toString(2).getBytes(StandardCharsets.UTF_8);if(manifest.length>1024*1024)throw new IOException("Export metadata exceeds its limit.");
        }
        void write(OutputStream output,BooleanSupplier active)throws Exception {if(encoded.size()!=parts.size()||manifest==null)throw new IOException("Encoded export is not complete.");if(parts.size()==1){try(RandomAccessFile in=new RandomAccessFile(encoded.get(0),"r")){copy(in,output,in.length(),active);}output.flush();return;}ZipOutputStream zip=new ZipOutputStream(output,StandardCharsets.UTF_8);zip.setLevel(Deflater.NO_COMPRESSION);for(int i=0;i<encoded.size();i++){NightAudioArchive.active(active);ZipEntry entry=new ZipEntry(String.format(Locale.ROOT,"recordings/%03d.m4a",i+1));entry.setTime(0);zip.putNextEntry(entry);try(RandomAccessFile in=new RandomAccessFile(encoded.get(i),"r")){copy(in,zip,in.length(),active);}zip.closeEntry();}zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(manifest);zip.closeEntry();zip.finish();zip.flush();}
        public void close()throws IOException{workspace.close();}
    }
    static Snapshot stage(Context app,Store store,Plan plan,long record,boolean favorites,List<Integer> selected,BooleanSupplier active)throws Exception {
        if(selected.isEmpty()||selected.size()>MAX_PARTS)throw new IOException("Select at least one audio interval.");List<Part> parts=new ArrayList<>();Set<Integer> seen=new HashSet<>();for(int n:selected){if(n<0||n>=plan.parts.size()||!seen.add(n))throw new IOException("Invalid audio selection.");parts.add(plan.parts.get(n));}Workspace workspace=Workspace.create(app);try{synchronized(SoundClips.LOCK){NightAudioArchive.active(active);if(!metadata(store,record,favorites).fingerprint.equals(plan.fingerprint))throw new IOException("The night or favorites changed. Refresh before exporting.");for(Part part:parts){Source source=part.source;if(workspace.sources.containsKey(source.clip.getLong("id")))continue;File target=workspace.allocate(source);try(RandomAccessFile in=new RandomAccessFile(FileSafety.clip(app,source.clip.getString("path")),"r");FileOutputStream out=new FileOutputStream(target)){if(!copy(in,out,source.bytes,active).equals(source.hash))throw new IOException("A recording changed. Refresh before exporting.");out.getFD().sync();}}
                if(!metadata(store,record,favorites).fingerprint.equals(plan.fingerprint))throw new IOException("The recordings changed. Refresh before exporting.");}return new Snapshot(workspace,List.copyOf(parts));}catch(Exception failure){try{workspace.close();}catch(IOException cleanup){failure.addSuppressed(cleanup);}throw failure;}
    }
    private static final class Workspace implements AutoCloseable {
        static final Semaphore ACTIVE=new Semaphore(1);final File directory;final Map<Long,File> sources=new HashMap<>();boolean closed;
        Workspace(File directory){this.directory=directory;}
        static Workspace create(Context app)throws IOException {if(!ACTIVE.tryAcquire())throw new IOException("Another AAC export is still finishing.");try{File cache=app.getCacheDir().getCanonicalFile(),root=new File(cache,"aac-recording-exports");if(!root.getCanonicalFile().equals(root.getAbsoluteFile()))throw new IOException("Invalid private export cache.");if(!root.isDirectory()&&!root.mkdir())throw new IOException("Private export cache unavailable.");File[] stale=root.listFiles();if(stale==null||stale.length>128)throw new IOException("Private export cache unavailable.");for(File dir:stale){if(!dir.getName().matches("export-[0-9a-f-]{36}"))throw new IOException("Unknown private export cache entry.");remove(root,dir);}File directory=new File(root,"export-"+UUID.randomUUID());if(!directory.mkdir())throw new IOException("Private export cache unavailable.");return new Workspace(directory);}catch(IOException|RuntimeException error){ACTIVE.release();throw error;}}
        File file(int index,String extension){if(closed||index<0||index>=MAX_PARTS||!List.of("wav","m4a").contains(extension))throw new IllegalStateException("Export snapshot unavailable.");return new File(directory,String.format(Locale.ROOT,"%03d.%s",index+1,extension));}
        File allocate(Source source)throws Exception {File file=file(sources.size(),"wav");sources.put(source.clip.getLong("id"),file);return file;}File source(Source source){return sources.get(source.clip.optLong("id"));}
        static void remove(File root,File directory)throws IOException {if(!directory.getCanonicalFile().equals(directory.getAbsoluteFile())||!directory.getCanonicalFile().getParentFile().equals(root.getCanonicalFile())||!directory.isDirectory())throw new IOException("Invalid private export cache.");File[] files=directory.listFiles();if(files==null||files.length>MAX_PARTS*2)throw new IOException("Private export cleanup failed.");for(File file:files)if(!file.getName().matches("[0-9]{3}\\.(wav|m4a)")||!file.getCanonicalFile().equals(file.getAbsoluteFile())||!file.getParentFile().equals(directory)||!file.isFile()||!file.delete())throw new IOException("Private export cleanup failed.");if(!directory.delete())throw new IOException("Private export cleanup failed.");}
        public void close()throws IOException{if(closed)return;closed=true;try{remove(directory.getParentFile(),directory);}finally{ACTIVE.release();}}
    }
    private AacArchive(){}
}
